{"content":"import numpy as np
from scipy.optimize import minimize
rng=np.random.default_rng(42)
for alpha in [.16,1/6,.17,.18,.19,.2,.21,.25,.3,.4]:
 for k,nr in [(2,1),(3,1),(4,1),(4,2),(5,1)]:
  inds=np.triu_indices(k,1); L=len(inds[0]);diag=np.r_[np.ones(nr),np.zeros(k-nr)]
  def calc(x):
   w=x[:k];P=np.diag(diag);P[inds]=x[k:k+L];P=P+P.T-np.diag(diag)
   R=(P*w)@P;Q=1-P;B=(Q*w)@Q
   return w,P,R,B
  def con(x):
   w,P,R,B=calc(x);t=x[-1]
   return np.r_[alpha*t-R[inds],t-B[inds],alpha*t-np.diag(R)[:nr],t-np.diag(B)[nr:]]
  best=None
  for j in range(30):
   x=np.r_[rng.dirichlet(np.ones(k)*2),rng.uniform(.1,.9,L),.5]
   r=minimize(lambda x:x[-1],x,bounds=[(1e-8,1)]*k+[(1e-8,1-1e-8)]*L+[(.01,1)],constraints=[{'type':'eq','fun':lambda x:sum(x[:k])-1},{'type':'ineq','fun':con}],method='SLSQP',options={'maxiter':500,'ftol':1e-10})
   if r.success and (best is None or r.fun<best.fun):best=r
  print(alpha,k,nr,round(1/best.fun,8),np.round(best.x,4),flush=True)
","timeout_seconds":200}

