import numpy as np, networkx as nx
from scipy.optimize import minimize
rng=np.random.default_rng(44)
graphs=[g for g in nx.graph_atlas_g() if 2<=len(g)<=6 and nx.is_connected(g)]
for alpha in [.17,.18,.19,.2,.201,.21]:
 best=(0,None,None)
 for g in graphs:
  k=len(g);edges=list(g.edges()); inds=tuple(np.array(edges).T); L=len(edges);allinds=np.triu_indices(k,1)
  def calc(x):
   w=x[:k];P=np.zeros((k,k));P[inds]=x[k:k+L];P+=P.T
   R=(P*w)@P;Q=1-P;B=(Q*w)@Q
   return R,B
  def con(x):
   R,B=calc(x);t=x[-1]
   return np.r_[alpha*t-R[inds],t-np.diag(B)]
  for j in range(2):
   x=np.r_[rng.dirichlet(np.ones(k)*3),rng.uniform(.3,.7,L),.5]
   r=minimize(lambda x:x[-1],x,bounds=[(1e-8,1)]*k+[(1e-6,1)]*L+[(.01,1)],constraints=[{'type':'eq','fun':lambda x:sum(x[:k])-1},{'type':'ineq','fun':con}],method='SLSQP',options={'maxiter':200,'ftol':1e-9})
   if r.success and 1/r.fun>best[0]:best=(1/r.fun,edges,r.x)
 print(alpha,best,flush=True)

