{"content":"import numpy as np
from scipy.optimize import linprog
from itertools import combinations_with_replacement
G=np.linspace(0,1,41)
pts=[]
for x0 in G:
 for x,y in combinations_with_replacement(G,2):
  pts.append((x0,x,y,0))
for x,y,z in combinations_with_replacement(G,3):pts.append((1,x,y,z))
P=np.array(pts);X=P[:,0];S=P[:,1:].sum(axis=1);S2=(P[:,1:]**2).sum(axis=1);pairs=(S*S-S2)/2
A=np.array([X*X,pairs/3,(3-2*S+S2)/3,X*S/3,(1-X)*(3-S)/3])
for a in [.075,.08,1/12,.085,.09,.095,.096,.1]:
 b=min(.5,1-4*np.sqrt(a/3)+2*a,(1-np.sqrt(a))**2)-1e-5
 r=linprog(np.zeros(len(P)),A_ub=A,b_ub=[a,a,b,a,b],A_eq=np.ones((1,len(P))),b_eq=[1],bounds=(0,None),method='highs')
 print(a,b,r.success)
 if r.success:
  ix=np.where(r.x>1e-5)[0]
  print([(np.round(P[i],4),round(r.x[i],6)) for i in ix])
","timeout_seconds":200}

